const updateDebtFromStatementParse = `-- name: UpdateDebtFromStatementParse :exec
UPDATE debts
SET
    min_payment = CASE WHEN $1 > 0 THEN $1 ELSE min_payment END,
    minimum_obligation = CASE WHEN $1 > 0 THEN $1 ELSE minimum_obligation END,
    principal_decimal = CASE WHEN $2 > 0 THEN $2 ELSE principal_decimal END,
    due_date = COALESCE($3, due_date),
    updated_at = now()
WHERE id = $4
`

